    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: system-ui, -apple-system, sans-serif;
    background-color: #1a1a2e;
    color: #e0e0e0;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 20px;
}

#container {
    width: 100%;
    max-width: 900px;
    background-color: #16213e;
    border-radius: 12px;
    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.5);
    padding: 2rem;
}

h1 {
    font-size: 1.75rem;
    font-weight: 700;
    color: #e0e0e0;
    margin-bottom: 1.5rem;
    text-align: center;
}

#controls {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    align-items: center;
    justify-content: center;
    margin-bottom: 1.5rem;
}

button {
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: transform 0.2s, background-color 0.2s;
    color: #1a1a2e;
    background-color: #4fc3f7;
}

button:hover {
    transform: scale(1.05);
    background-color: #39e6c4;
}

button:active {
    transform: scale(0.98);
}

#speed-slider {
    width: 150px;
    cursor: pointer;
}

#speed-value {
    min-width: 40px;
    text-align: center;
    color: #94a0c4;
}

#comparison-counter {
    min-width: 150px;
    text-align: center;
    color: #94a0c4;
    font-size: 1rem;
}

#bars-container {
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 300px;
    padding: 1rem;
    background-color: #1a1a2e;
    border-radius: 8px;
}

.bar {
    flex: 1;
    background-color: #4fc3f7;
    border-radius: 4px 4px 0 0;
    transition: background-color 0.2s, height 0.1s ease;
    min-height: 2px;
}

.bar.comparing {
    background-color: #ff9800;
}

.bar.sorted {
    background-color: #66bb6a;
}

@media (max-width: 640px) {
    body {
        padding: 10px;
    }

    #container {
        padding: 1rem;
    }

    h1 {
        font-size: 1.5rem;
    }

    #controls {
        flex-direction: column;
        align-items: stretch;
    }

    #speed-slider {
        width: 100%;
    }

    #comparison-counter {
        min-width: auto;
    }

    #bars-container {
        height: 200px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .bar {
        transition: none;
    }
}""")
```

